        html += '<button data-sbg="' + b.id + '" style="text-align:left;padding:8px;border-radius:14px;cursor:pointer;background:var(--surface-card);border:2px solid ' + (sel ? 'var(--accent)' : 'var(--border-card)') + '">' + swatchPreview(previewCss(b), b.anim) + '<div style="display:flex;align-items:center;gap:5px;margin-top:8px;padding:0 2px"><span style="font-size:12.5px;font-weight:600;color:var(--text-strong);flex:1">' + b.name + '</span>' + (b.anim ? '<span class="material-symbols-rounded" style="' + ms + 'font-size:15px;color:var(--accent)">motion_photos_on</span>' : '') + (sel ? '<span class="material-symbols-rounded" style="' + ms + 'font-size:16px;color:var(--accent)">check_circle</span>' : '') + '</div></button>';
